s" media="all" href="/assets/wp-content/cache/breeze-minification/css/breeze_hipaa-policy-1-155-font-awesome-css-fontawesome-5840bad6deb3.css" rel="stylesheet" /><link type="text/css" media="all" href="/assets/wp-content/cache/breeze-minification/css/breeze_hipaa-policy-1-155-font-awesome-css-solid-9a5537071e42.css" rel="stylesheet" /><link type="text/css" media="all" href="/assets/wp-content/cache/breeze-minification/css/breeze_hipaa-policy-1-155-elementor-css-post-155-d73d5a3865b4.dl.css" rel="stylesheet" /><link type="text/css" media="all" href="/assets/wp-content/cache/breeze-minification/css/breeze_hipaa-policy-1-155-elementor-css-post-168-e3485ffdfed1.dl.css" rel="stylesheet" /><link type="text/css" media="all" href="/assets/wp-content/cache/breeze-minification/css/breeze_hipaa-policy-1-155-elementor-css-post-181-2fbefd2abe51.dl.css" rel="stylesheet" /><link type="text/css" media="all" href="/assets/wp-content/cache/breeze-minification/css/breeze_hipaa-policy-1-155-assets-css-widget-styles-ee65198370f3.dl.css" rel="stylesheet" /><link type="text/css" media="all" href="/assets/wp-content/cache/breeze-minification/css/breeze_hipaa-policy-1-155-assets-css-responsive-ed71c5d46516.css" rel="stylesheet" /><link type="text/css" media="all" href="/assets/wp-content/cache/breeze-minification/css/breeze_hipaa-policy-1-155-google-fonts-css-roboto-5868830012a3.css" rel="stylesheet" /><link type="text/css" media="all" href="/assets/wp-content/cache/breeze-minification/css/breeze_hipaa-policy-1-155-google-fonts-css-robotoslab-85bc2fa1e7b8.css" rel="stylesheet" /><link type="text/css" media="all" href="/assets/wp-content/cache/breeze-minification/css/breeze_lpa-2-1-208-google-fonts-css-figtree-28fbb3c89a73.css" rel="stylesheet" /><link type="text/css" media="all" href="/assets/wp-content/cache/breeze-minification/css/breeze_hipaa-policy-1-155-assets-css-ekiticons-2285e296fbb7.css" rel="stylesheet" /></head><body itemtype='https://schema.org/WebPage' itemscope='itemscope' cla